#include <iostream>
#include <string>
#include <vector>

class RegistroVisitas {
public:
    int visitas() { return visitas_; }
    bool registrar() {
        if (visitas_ >= 3) { return false; }
        ++visitas_;
        return true;
    }
private:
    int visitas_ = 0;
};

int main() {
    RegistroVisitas registro;
    for (int i = 0; i < 4; ++i) {
        bool aceptado = registro.registrar();
        std::cout << aceptado << ":" << registro.visitas() << ";";
    }
    return 0;
}
